"""Offline listening gallery, comparable rank plots and auditable pair report."""
from pathlib import Path
import json,html,base64,hashlib
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from matplotlib.colors import LogNorm

ROOT=Path(__file__).resolve().parent;OUT=ROOT/'similar_voice_pairs';FIG=OUT/'figures';FIG.mkdir(exist_ok=True)
selected=pd.read_csv(OUT/'selected_pairs.csv');assets=json.loads((OUT/'audio_assets.json').read_text(encoding='utf-8'));metrics=json.loads((OUT/'key_metrics.json').read_text())
from audit_voice_pair_matching import audit
matching_audit=audit()
names={'acoustic':'Acoustic','ecapa':'ECAPA','hybrid':'Hybrid','consensus':'Consensus'}
labels=[names[r.selection_method]+' #'+str(r.within_method_rank) for r in selected.itertuples()]
percent=selected[['acoustic_percentile','ecapa_percentile','hybrid_percentile']].to_numpy()*100
fig,ax=plt.subplots(figsize=(11,max(6,len(selected)*.38)));im=ax.imshow(percent,cmap='RdYlGn_r',norm=LogNorm(vmin=.01,vmax=100),aspect='auto')
ax.set_xticks(range(3),['Acoustic distance','ECAPA cosine distance','Hybrid distance']);ax.set_yticks(range(len(selected)),labels)
for i in range(len(selected)):
    for j in range(3):ax.text(j,i,f'{percent[i,j]:.2f}%',ha='center',va='center',fontsize=10)
ax.set_title('Rank among 5,308 controlled pairs: lower percentile = closer\nDifferent methods have different raw distance scales; ranks are not human quality scores')
fig.colorbar(im,ax=ax,label='Percentile rank (%), logarithmic colour scale');fig.tight_layout();fig.savefig(FIG/'pair_rank_comparison.png',dpi=160);plt.close(fig)
fig,ax=plt.subplots(figsize=(11,max(5,len(selected)*.32)));y=np.arange(len(selected));ax.barh(y-.16,selected.real_duration_s,height=.3,label='Real');ax.barh(y+.16,selected.synthetic_duration_s,height=.3,label='Synthetic');ax.set_yticks(y,labels);ax.set(xlabel='Seconds',title='Same count: 8 words; duration gap <=0.5 s; texts differ');ax.legend();fig.tight_layout();fig.savefig(FIG/'pair_duration_controls.png',dpi=160);plt.close(fig)

blind_codes={'acoustic':'B','ecapa':'C','hybrid':'A','consensus':'D'}
previous=json.loads((OUT/'gallery_data.json').read_text(encoding='utf-8')) if (OUT/'gallery_data.json').exists() else []
previous_A={r['pair_id']:r['sides']['A']['sample_id'] for r in previous}
order={r.pair_id:(previous_A[r.pair_id]==r.real_sample if r.pair_id in previous_A else bool(int(hashlib.sha256(r.pair_id.encode()).hexdigest()[0],16)%2)) for r in selected.itertuples()}
cards=[]
for r in selected.to_dict('records'):
    real=assets[r['real_sample']];syn=assets[r['synthetic_sample']]
    a,b=(real,syn) if order[r['pair_id']] else (syn,real)
    cards.append({**r,'matching_audit':matching_audit[(r['selection_method'],r['within_method_rank'])],'blind_code':blind_codes[r['selection_method']],'sides':{'A':a,'B':b}})
payload=json.dumps(cards,ensure_ascii=False).replace('</','<\\/')
audio_sources={}
for a in assets.values():
    for key in ['raw_audio','level_audio']:
        path=OUT/a[key]
        audio_sources[a[key]]='data:audio/wav;base64,'+base64.b64encode(path.read_bytes()).decode('ascii')
template='''<!doctype html><html lang="he" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>השוואת זוגות קול</title><style>
*{box-sizing:border-box}body{font-family:Arial,sans-serif;margin:0;background:#f2f5f8;color:#193047}main{max-width:1160px;margin:auto;padding:24px}h1{font-size:28px;margin-bottom:8px}.intro,.toolbar,.card{background:white;border:1px solid #d5e0e7;border-radius:12px;padding:20px;margin-bottom:18px;line-height:1.6}.intro{border-right:5px solid #00858d}.toolbar{display:flex;flex-wrap:wrap;gap:14px;align-items:center}button,select,input,textarea{font:inherit}button,select{padding:9px 13px;border:1px solid #b6c9d5;border-radius:7px;background:#fff;color:#193047;cursor:pointer}button{background:#e6f3f4}label{display:block}audio{width:100%;margin:8px 0}.sides{display:grid;grid-template-columns:1fr 1fr;gap:20px}.side{padding:14px;background:#f5f8fa;border-radius:8px}details{margin:12px 0}summary{cursor:pointer;color:#007b83}textarea{width:100%;min-height:65px;border:1px solid #cad7df;border-radius:6px;padding:9px}.ratings{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}small,.muted{color:#506574}.tag{display:inline-block;padding:3px 9px;border-radius:20px;background:#e6f3f4;font-size:13px}img{width:100%;height:auto;border:1px solid #dae4ea;border-radius:8px}code{direction:ltr;unicode-bidi:embed;overflow-wrap:anywhere}#status{font-size:14px}.hidden{display:none}@media(max-width:700px){main{padding:12px}.sides,.ratings{grid-template-columns:1fr}h1{font-size:23px}}</style>
<main><h1>שישה זוגות בכל קבוצה — השוואה בין שיטות</h1><div class="intro"><b>בכל קבוצה שש דוגמאות בעלות ציון ההתאמה היחסי הגבוה ביותר תחת אילוצי גיוון.</b> A = שילוב אקוסטיקה ו־ECAPA; B = אקוסטיקה; C = ECAPA. קבוצת ההסכמה מתחשבת בשלוש השיטות יחד. בכל קבוצה שישה דוברים אמיתיים ושישה קולות מסונתזים שונים, ולכל היותר שלושה זוגות מאותה משפחת ספק.<br>בכל זוג יש הקלטה אמיתית ואחת מסונתזת. הצדדים א׳/ב׳ הוחלפו באקראי. הטקסטים שונים, אך בכל צד שמונה מילים והפרש משך של עד חצי שנייה. לא הופק אודיו חדש, והמסונתז אינו חיקוי מאומת של האדם.<br><small>ברירת המחדל היא עוצמת האזנה מותאמת בלבד; ללא שינוי מהירות או חיתוך מילים. כדאי לדרג לפני חשיפת זהויות ושיטות. ציון ההתאמה הוא 100 פחות אחוזון המרחק: גבוה יותר קרוב יותר. הוא אינו הסתברות לאותה זהות או ציון איכות אנושי.</small></div>
<div class="toolbar"><label>דוגמאות <select id="method"><option value="consensus">שישה זוגות הסכמה</option><option value="hybrid">A — שילוב</option><option value="acoustic">B — אקוסטיקה</option><option value="ecapa">C — ECAPA</option><option value="all">הכול</option></select></label><label>עוצמה <select id="level"><option value="level_audio">עוצמת האזנה מותאמת</option><option value="raw_audio">עוצמה מקורית</option></select></label><button id="reveal">חשיפת השיטות וזהויות המקור</button><button id="export">ייצוא הדירוגים ל־JSON</button><span id="status"></span></div><div id="cards"></div>
<details><summary>איך נבחרו הזוגות ומה אפשר להסיק?</summary><p>נבדקו 5,308 זוגות מועמדים: 32 קטעים מ־26 דוברים אמיתיים מול קטעים מסונתזים המתאימים לתנאי האורך. כל שיטה בחרה שישה זוגות שממזערים יחד את המרחק, עם שישה דוברים אמיתיים ושש קבוצות קול שונות, ולכל היותר שלושה זוגות למשפחת ספק. זוגות ההסכמה ממזערים את אחוזון המרחק הגרוע ביותר בין שלושת המדדים.</p><p>אקוסטיקה משתמשת בתשעה פיצ׳רים, כגון עוצמה ושקט. ECAPA משתמש בייצוג קולי בן 192 ממדים. השילוב מאזן בין שני הבלוקים. המיון נעשה במרחבי הפיצ׳רים המקוריים, לא על מפת PCA או על מספר האשכול. שש דוגמאות לשיטה אינן מספיקות לקבוע איזו שיטה טובה יותר באופן כללי.</p><p>זוג שנבחר ביותר משיטה אחת מופיע בכל קבוצה רלוונטית, אך דירוגיו משותפים ואינם נספרים כהערכות עצמאיות. הקולות והגבולות לא קיבלו אימות אנושי חדש; הדרוגים כאן אינם משנים את תוויות המאגר.</p></details>
<details><summary>גרפים ודירוגים מספריים — רצוי לפתוח אחרי ההאזנה</summary><img src="figures/pair_rank_comparison.png" alt="אחוזוני מרחק בשלושת המדדים"><img src="figures/pair_duration_controls.png" alt="בקרת משכים"></details></main>
<script>const DATA=__DATA__;const AUDIO_SOURCES=__AUDIO_SOURCES__;const METHOD_NAMES={acoustic:'פיצ׳רים אקוסטיים',ecapa:'ECAPA',hybrid:'אקוסטיקה + ECAPA',consensus:'הסכמה בין שלושת המדדים'};const UNIQUE_PAIRS=new Set(DATA.map(d=>d.pair_id)).size;let revealed=false;let ratings={};try{ratings=JSON.parse(localStorage.getItem('hebrew_similar_voice_pairs_v1')||'{}')}catch(e){}const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function ratingControl(pid,key,title){const value=ratings[pid]?.[key]??'';return `<label>${title}<select data-pid="${esc(pid)}" data-key="${key}"><option value="">טרם דורג</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${String(value)===String(n)?'selected':''}>${n}</option>`).join('')}</select></label>`}
function render(){document.querySelectorAll('audio').forEach(a=>a.pause());const method=document.getElementById('method').value,level=document.getElementById('level').value;document.getElementById('cards').innerHTML=DATA.filter(d=>method==='all'||d.selection_method===method).map(d=>{const title=d.selection_method==='consensus'?'זוג הסכמה':revealed?METHOD_NAMES[d.selection_method]:'שיטה '+d.blind_code;return `<article class="card"><h2>${title} — זוג ${d.within_method_rank}</h2><span class="tag">ציון התאמה יחסי ${d.relative_match_score.toFixed(2)} / 100</span> <span class="tag">8 מילים בכל צד</span> <span class="tag">פער משך ${d.duration_gap_s.toFixed(2)} שניות</span><div class="sides">${['A','B'].map((side,i)=>{const a=d.sides[side];return `<section class="side"><b>הקלטה ${i===0?'א׳':'ב׳'} ${revealed?'— '+(a.label==='real'?'אמיתית':'מסונתזת'):''}</b><audio controls preload="none" src="${esc(a[level])}"></audio><small>${a.duration_s.toFixed(2)} שניות</small>${revealed?`<p>${esc(a.text)}</p><p class="muted"><code>${esc(a.model)} / ${esc(a.voice)}</code></p>`:''}</section>`}).join('')}</div><p><b>דמיון קולי:</b> 1 = שונים מאוד, 5 = דומים מאוד. <b>טבעיות:</b> 1 = לא טבעי, 5 = טבעי מאוד.</p><div class="ratings">${ratingControl(d.pair_id,'voice_similarity','דמיון בין הקולות')}${ratingControl(d.pair_id,'naturalness_A','טבעיות הקלטה א׳')}${ratingControl(d.pair_id,'naturalness_B','טבעיות הקלטה ב׳')}</div><label>הערות<textarea data-pid="${esc(d.pair_id)}" data-key="notes">${esc(ratings[d.pair_id]?.notes||'')}</textarea></label>${revealed?`<details><summary>פרטי בחירה ומרחקים</summary><p>מודל מסונתז: <code>${esc(d.model)}</code>; קול: <code>${esc(d.voice)}</code></p><p>אחוזוני המרחקים — נמוך יותר קרוב יותר: אקוסטיקה ${(100*d.acoustic_percentile).toFixed(2)}%, ECAPA ${(100*d.ecapa_percentile).toFixed(2)}%, שילוב ${(100*d.hybrid_percentile).toFixed(2)}%.</p><p class="muted">מזהה: <code>${esc(d.pair_id)}</code></p></details>`:''}</article>`}).join('');document.querySelectorAll('audio').forEach(a=>a.addEventListener('play',()=>document.querySelectorAll('audio').forEach(b=>{if(a!==b)b.pause()})));document.querySelectorAll('[data-key]').forEach(el=>el.addEventListener('change',()=>{const pid=el.dataset.pid;ratings[pid]??={};ratings[pid][el.dataset.key]=el.value;ratings[pid].updated_utc=new Date().toISOString();localStorage.setItem('hebrew_similar_voice_pairs_v1',JSON.stringify(ratings));status()}));status()}
function status(){document.getElementById('status').textContent='דורגו '+Object.values(ratings).filter(x=>x.voice_similarity).length+' מתוך '+UNIQUE_PAIRS+' זוגות ייחודיים; נשמר בדפדפן בלבד'}
document.getElementById('method').addEventListener('change',render);document.getElementById('level').addEventListener('change',render);document.getElementById('reveal').addEventListener('click',()=>{revealed=!revealed;document.getElementById('reveal').textContent=revealed?'הסתרת הפרטים':'חשיפת השיטות וזהויות המקור';render()});document.getElementById('export').addEventListener('click',()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({schema_version:'1.0',exported_utc:new Date().toISOString(),ratings,side_assignments:DATA.map(d=>({pair_id:d.pair_id,A:d.sides.A.sample_id,B:d.sides.B.sample_id,selection_method:d.selection_method})),listening_level:document.getElementById('level').value,methods_revealed:revealed},null,2)],{type:'application/json'}));a.download='voice_pair_listening_ratings.json';a.click();URL.revokeObjectURL(a.href)});render();</script></html>'''
